<script setup lang="ts">
import { LayoutDashboard, Package, ClipboardList, ExternalLink, LogOut, Menu, X } from 'lucide-vue-next'
// A fresh request is essential after login: useFetch can reuse the anonymous session
// that the login page cached during the same client-side navigation.
const session = await useRequestFetch()< { authenticated: boolean } >('/api/admin/session', { headers: adminHeaders() })
if (!session.authenticated) await navigateTo('/admin/login')
const open = ref(false)
const route = useRoute()
watch(() => route.fullPath, () => open.value = false)
async function logout() { await $fetch('/api/admin/logout', { method: 'POST', headers: adminHeaders() }); sessionStorage.removeItem('pile-preview-session'); await navigateTo('/admin/login') }
</script>
<template><div class="admin-shell"><aside class="admin-sidebar" :class="{open}"><NuxtLink to="/admin" class="admin-brand">پیله پاتری<span>.</span><small>مدیریت فروشگاه</small></NuxtLink><div class="sidebar-label">فضای کار</div><nav><NuxtLink to="/admin" exact-active-class="selected"><LayoutDashboard :size="18"/> پیشخوان</NuxtLink><NuxtLink to="/admin/products" active-class="selected"><Package :size="18"/> محصولات</NuxtLink><NuxtLink to="/admin/orders" active-class="selected"><ClipboardList :size="18"/> سفارش‌ها و پرداخت‌ها</NuxtLink></nav><div class="sidebar-bottom"><NuxtLink to="/" target="_blank"><ExternalLink :size="17"/> مشاهده‌ی سایت</NuxtLink><button @click="logout"><LogOut :size="17"/> خروج از حساب</button></div></aside><div v-if="open" class="admin-overlay" @click="open=false"></div><div class="admin-main"><header class="admin-topbar"><button class="admin-mobile-toggle" aria-label="منو" @click="open=!open"><X v-if="open" :size="22"/><Menu v-else :size="22"/></button><span>پنل مدیریت پیله پاتری <small>/ {{ route.path === '/admin' ? 'پیشخوان' : route.path.includes('products') ? 'محصولات' : 'سفارش‌ها' }}</small></span><span class="admin-avatar">پ</span></header><div class="admin-content"><slot /></div></div></div></template>
